def access_elements(nums, list_index):
    result = [nums[i] for i in list_index]
    return result

def check(s):
    val = 0
    for i in s:
        if i == '(':
            val = val + 1
        else:
            val = val - 1
        if val < 0:
            return False
    return True if val == 0 else False

S1 = lst[0] + lst[1]
S2 = lst[1] + lst[0]
return 'Yes' if check(S1) or check(S2) else 'No'
